const j = $input.item.json;
const trig = $('Gmail Trigger').itemMatching($itemIndex);
const bin = ($input.item.binary && Object.keys($input.item.binary).length) ? $input.item.binary : (trig.binary || {});
const keys = Object.keys(bin);
const isPdf = (b) => b && (String(b.mimeType || '').includes('pdf') || /\.pdf$/i.test(String(b.fileName || '')));
const pdfKeys = keys.filter((k) => isPdf(bin[k]));
const best = pdfKeys.find((k) => /cv|resume|résumé|curriculum/i.test(String(bin[k].fileName || ''))) || pdfKeys[0];

const from = (j.headers && j.headers.from) || (j.from && j.from.text) || '';
const m = String(from).match(/([A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,})/);
const email = m ? m[1] : '';
let name = String(from).replace(/<[^>]*>/g, '').replace(/["']/g, '').trim();
if (!name || name.includes('@')) name = email ? email.split('@')[0] : 'Candidate';
const canAck = !!email && !/no-?reply|do-?not-?reply|mailer-daemon|postmaster/i.test(email);

const out = {
  json: {
    hrEmail: j.hrEmail, companyName: j.companyName, jobTitle: j.jobTitle, jobDescription: j.jobDescription,
    mustHaves: j.mustHaves, shortlistScore: j.shortlistScore, reviewScore: j.reviewScore, sendAck: j.sendAck,
    candidateName: name, candidateEmail: email, canAck,
    subject: String(j.subject || '(no subject)'),
    coverNote: String(j.text || j.snippet || '').slice(0, 1500),
    threadId: j.threadId,
    mailLink: 'https://mail.google.com/mail/u/0/#all/' + (j.threadId || ''),
    hasCv: !!best, cvFileName: best ? (bin[best].fileName || 'cv.pdf') : '', attachmentCount: keys.length
  }
};
if (best) out.binary = { data: bin[best] };
return out;

const c = $('Pick CV Attachment').itemMatching($itemIndex).json;
const ai = $input.item.json.output || null;
const esc = (s) => String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');

let score = null, decision = 'MANUAL REVIEW';
if (ai && typeof ai.score === 'number') {
  score = Math.max(0, Math.min(100, Math.round(ai.score)));
  decision = score >= Number(c.shortlistScore) ? 'SHORTLIST' : score >= Number(c.reviewScore) ? 'REVIEW' : 'NOT A MATCH';
}
const style = {
  'SHORTLIST': { color: '#188038', emoji: '🌟' },
  'REVIEW': { color: '#e8710a', emoji: '🟠' },
  'NOT A MATCH': { color: '#d93025', emoji: '🔴' },
  'MANUAL REVIEW': { color: '#5f6368', emoji: '⚠️' }
}[decision];

const li = (arr, f) => (arr && arr.length ? arr.map(f).join('') : '<li>None</li>');
const statusIcon = { met: '✅', partial: '🟡', not_met: '❌' };
const mustRows = ai && ai.mustHaves && ai.mustHaves.length
  ? ai.mustHaves.map((m) => '<tr><td style="padding:6px 8px;border-bottom:1px solid #eee">' + (statusIcon[m.status] || '•') + ' ' + esc(m.requirement) + '</td><td style="padding:6px 8px;border-bottom:1px solid #eee;color:#555">' + esc(m.evidence) + '</td></tr>').join('')
  : '<tr><td style="padding:6px 8px" colspan="2">No must-have requirements were set.</td></tr>';

const body = ai
  ? '<h3 style="margin:18px 0 4px">Summary</h3><p style="margin:0">' + esc(ai.summary) + '</p>' +
    '<p style="margin:10px 0 0"><b>Current role:</b> ' + esc(ai.currentRole) + ' &nbsp;|&nbsp; <b>Experience:</b> ~' + esc(ai.yearsExperience) + ' yrs<br><b>Top skills:</b> ' + esc((ai.topSkills || []).join(', ')) + '</p>' +
    '<h3 style="margin:18px 0 4px">Must-have check</h3><table style="width:100%;border-collapse:collapse;font-size:13px">' + mustRows + '</table>' +
    '<h3 style="margin:18px 0 4px">Strengths</h3><ul style="margin:0">' + li(ai.strengths, (s) => '<li><b>' + esc(s.title) + ':</b> ' + esc(s.evidence) + '</li>') + '</ul>' +
    '<h3 style="margin:18px 0 4px">Gaps and concerns</h3><ul style="margin:0">' + li(ai.gaps, (g) => '<li><b>' + esc(g.title) + ':</b> ' + esc(g.detail) + '</li>') + '</ul>' +
    '<h3 style="margin:18px 0 4px">Suggested interview questions</h3><ol style="margin:0">' + li(ai.interviewQuestions, (q) => '<li>' + esc(q) + '</li>') + '</ol>'
  : '<p>The AI service was unavailable, so no automatic score was produced. Please review this CV manually.</p>';

const bar = score === null ? '' :
  '<div style="background:rgba(255,255,255,.35);border-radius:6px;height:10px;margin-top:10px"><div style="width:' + score + '%;background:#fff;height:10px;border-radius:6px"></div></div>';

const reportHtml =
  '<div style="font-family:Arial,Helvetica,sans-serif;max-width:680px;margin:auto;border:1px solid #ddd;border-radius:10px;overflow:hidden">' +
  '<div style="background:' + style.color + ';color:#fff;padding:18px 22px"><div style="font-size:12px;letter-spacing:1px">AI CV SCREENING SCORECARD | ' + esc(c.jobTitle).toUpperCase() + '</div>' +
  '<div style="font-size:26px;font-weight:bold;margin-top:4px">' + style.emoji + ' ' + decision + (score === null ? '' : ': ' + score + '/100') + '</div>' + bar + '</div>' +
  '<div style="padding:20px 22px;color:#222;font-size:14px;line-height:1.5">' +
  '<p style="margin-top:0"><b>Candidate:</b> ' + esc(c.candidateName) + ' (' + esc(c.candidateEmail || 'no email found') + ')<br><b>CV file:</b> ' + esc(c.cvFileName) + '<br><b>Email subject:</b> ' + esc(c.subject) + '<br><a href="' + esc(c.mailLink) + '">Open original email in Gmail</a></p>' +
  body + '</div>' +
  '<div style="background:#f5f5f5;color:#777;padding:10px 22px;font-size:12px">AI-assisted screening based only on job-relevant skills and experience. A human must make the final hiring decision.</div></div>';

const first = c.candidateName.includes(' ') || /^[A-Za-z]+$/.test(c.candidateName) ? c.candidateName.split(' ')[0] : '';
const ackHtml =
  '<div style="font-family:Arial,Helvetica,sans-serif;font-size:14px;line-height:1.6;color:#222">' +
  '<p>Hello' + (first ? ' ' + esc(first) : '') + ',</p>' +
  '<p>Thank you for applying for the <b>' + esc(c.jobTitle) + '</b> position at ' + esc(c.companyName) + '. We have received your CV and our hiring team will review it carefully.</p>' +
  '<p>If your profile matches what we are looking for, we will contact you about the next steps.</p>' +
  '<p>Best regards,<br>' + esc(c.companyName) + ' Talent Team</p></div>';

return { json: {
  hrEmail: c.hrEmail, decision, score, aiAvailable: !!ai,
  subjectLine: style.emoji + ' ' + decision + (score === null ? '' : ' (' + score + '/100)') + ': ' + c.candidateName + ' | ' + c.jobTitle,
  reportHtml, candidateEmail: c.candidateEmail, canAck: c.canAck, sendAck: c.sendAck === true || c.sendAck === 'true',
  ackSubject: 'We received your application: ' + c.jobTitle, ackHtml
} };
